type Punto = {x: number; y: number};
type Parada = [number, number, number, number];

const avance = (s: number, t: number, d = 0.8) =>
  interpolate(s, [t, t + d], [0, 1], clamp);

const mezclar = (a: Punto, b: Punto, k: number): Punto => ({
  x: a.x + (b.x - a.x) * k,
  y: a.y + (b.y - a.y) * k,
});

const encuadre = (s: number, paradas: Parada[]) => {
  const tiempos = paradas.map((p) => p[0]);
  const x = interpolate(s, tiempos, paradas.map((p) => p[1]), clamp);
  const y = interpolate(s, tiempos, paradas.map((p) => p[2]), clamp);
  const z = interpolate(s, tiempos, paradas.map((p) => p[3]), clamp);
  return `translate(540 960) scale(${z}) translate(${-x} ${-y})`;
};

